        r = _client._get(path)
        print('GET', path, r)
    except Exception as e:
        print('GET', path, 'ERR', e)

for path in ['/scripts', '/daily-scripts', '/register-script', '/register-daily-script']:
    try:
        r = _client._post(path, {'name': 'test'})
        print('POST', path, r)
    except Exception as e:
        print('POST', path, 'ERR', e)

# try call tools
for tool in ['register_daily_script', 'register_script', 'list_daily_scripts', 'list_scripts', 'register_daily_calculation']:
    try:
        r = _client.call(tool, {})
        print('CALL', tool, r)
    except Exception as e:
        print('CALL', tool, 'ERR', e)
"

