#!/usr/bin/env python3
"""Config, social, billing, quality history, scripts."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

print("=== CONFIG OVERRIDES ===")
for row in q("SELECT * FROM config_overrides"):
    print(row)

print("\n=== CONFIG HISTORY last rows ===")
for row in q("SELECT * FROM config_history ORDER BY day DESC LIMIT 8"):
    print(row)

print("\n=== AGENT SOCIAL POSTS ===")
for row in q("SELECT * FROM agent_social_media_posts"):
    print(row)

print("\n=== SOCIAL POSTS last 3d (ids) ===")
for row in q("SELECT post_id, day, group_id, substr(content,1,140) AS c, likes, comments, views FROM social_media_posts WHERE day>=26 ORDER BY day DESC, post_id DESC LIMIT 40"):
    print(row)

