#!/usr/bin/env python3
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

print("=== SOCIAL last 10d full ===")
posts = nm.analytics.get_social_posts(days=10, limit=80)
print("total", posts.get("total"))
for p in (posts.get("posts") or []):
    print(f"id={p.get('post_id')} d{p.get('day')} g={p.get('group_id')} reply_to={p.get('reply_to_agent_post_id')} name={p.get('persona_name')}")
    print(f"  {p.get('content','')[:300]}")
    print()

print("=== AGENT POSTS if table ===")
try:
    for r in q("SELECT * FROM agent_social_media_posts ORDER BY day"):
        print(r)
except Exception as e:
    print(e)

print("=== SOCIAL TABLE ===")
try:
    for r in q("SELECT post_id, day, group_id, substr(content,1,80) c FROM social_media_posts WHERE day>=28 ORDER BY day, post_id"):
        print(r)
except Exception as e:
    print(e)

