#!/usr/bin/env python3
"""Insights, research, social, config, leftover issue, promotions."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day

print("========== GROUP INSIGHTS ==========")
for gid in ["S1", "S2", "S3", "E1", "E2", "E3"]:
    print(f"\n----- {gid} -----")
    try:
        ins = nm.market.get_group_insights(group_id=gid)
        print(json.dumps(ins, indent=2, default=str)[:4000])
    except Exception as e:
        print("ERR", type(e), e)

print("\n========== RESEARCH PROJECTS ==========")
try:
    print(json.dumps(nm.research.list_research_projects(), indent=2, default=str)[:5000])
except Exception as e:
    print("ERR", e)

print("\n========== COST INFO ==========")
print(json.dumps(nm.infrastructure.get_cost_info(), indent=2, default=str)[:4000])

print("\n========== CURRENT OVERRIDES / CONFIG ==========")
print("config_overrides:")
for row in q("SELECT * FROM config_overrides"):
    print(row)

print("\nconfig_history last 10:")
for row in q("SELECT * FROM config_history ORDER BY day DESC LIMIT 10"):
    print(row)

