#!/usr/bin/env python3
"""Week 9 more intel: insights, social, R&D, config, quality, leftover renewals."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} MORE ===")

print("\n======= MARKET INSIGHTS S1 =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S1"), indent=2, default=str)[:8000])
except Exception as e:
    print("S1 insights", e)

print("\n======= MARKET INSIGHTS S3 =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S3"), indent=2, default=str)[:4000])
except Exception as e:
    print("S3 insights", e)

print("\n======= R&D PROJECTS =======")
try:
    print(json.dumps(nm.research.list_research_projects(), indent=2, default=str)[:6000])
except Exception as e:
    print(e)

print("\n======= SOCIAL POSTS (our posts + recent support) =======")
try:
    posts = nm.analytics.get_social_posts(days=10, limit=80)
    print(type(posts), len(posts) if hasattr(posts, '__len__') else '')
    if isinstance(posts, dict):
        print(list(posts.keys()))
        items = posts.get('posts') or posts.get('rows') or posts
    else:
        items = posts
    for p in items:
        if isinstance(p, dict):
            pid = p.get('post_id') or p.get('id')
            author = p.get('author') or p.get('group_id') or p.get('customer_id')
            dayp = p.get('day') or p.get('created_day')
            content = (p.get('content') or p.get('text') or '')[:180]
            ours = p.get('is_company') or p.get('author_type') or p.get('source')
            print(f"  id={pid} d={dayp} {author} ours={ours} | {content}")
        else:
            print(p)
except Exception as e:
    print("social", e)

print("\n======= SOCIAL TABLE =======")
try:
    for row in q("SELECT * FROM social_media_posts ORDER BY day DESC LIMIT 5"):
        print(row.keys() if hasattr(row, 'keys') else row)
        break
    cols = None
    for row in q("SELECT * FROM social_media_posts WHERE day >= 50 ORDER BY day DESC, post_id DESC LIMIT 40"):
        if cols is None:
            cols = list(row.keys())
            print("COLS", cols)
        print({k: row[k] for k in row if k != 'content'}, "|", str(row.get('content',''))[:140])
except Exception as e:
    print("soc table", e)

