#!/usr/bin/env python3
import novamind_api as nm, json

def q(sql):
    return (nm.query(sql).get("rows") or [])

print("daily_usage schema sample")
try:
    print(q("SELECT * FROM daily_usage LIMIT 2"))
except Exception as e:
    print(e)

print("\nusage last 3 days totals")
for row in q("SELECT * FROM daily_usage WHERE day>=68 LIMIT 20"):
    print(row)

print("\ncolumns from one sub + usage join attempt")
try:
    print(q("""
        SELECT s.plan, c.group_id, SUM(u.usage_units) tot, COUNT(*) n, AVG(u.usage_units) avg_u
        FROM daily_usage u
        JOIN subscriptions s ON s.customer_id=u.customer_id
        JOIN customers c ON c.customer_id=u.customer_id
        WHERE u.day=70 AND s.status='subscribed'
        GROUP BY s.plan, c.group_id
    """))
except Exception as e:
    print("join err", e)

print("\ncost info compute")
print(json.dumps(nm.infrastructure.get_cost_info(), indent=2, default=str)[:2500])

