#!/usr/bin/env python3
"""Week 11 intel: insights, social, config, E, leftover issues, research, quality path."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 11 INTEL ===")

print("\n======= MARKET OVERVIEW FULL =======")
print(json.dumps(nm.market.get_market_overview(), indent=2, default=str)[:4000])

print("\n======= S1 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S1"), indent=2, default=str)[:5000])
except Exception as e:
    print("S1 insights", e)

print("\n======= S3 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S3"), indent=2, default=str)[:4000])
except Exception as e:
    print(e)

print("\n======= S2 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S2"), indent=2, default=str)[:2500])
except Exception as e:
    print(e)

