#!/usr/bin/env python3
import novamind_api as nm
import json

posts = nm.analytics.get_social_posts(days=8, limit=20)
items = posts.get("posts") if isinstance(posts, dict) else posts
for p in items:
    pid = p.get("post_id")
    if pid in (211, 212, 210, 214, 213, 209):
        print("=" * 60)
        print(json.dumps(p, indent=2, default=str)[:2000])

print("\n=== DAILY SCRIPTS ===")
