import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 17 INTEL ===")

print("\n======= NOTIFICATIONS =======")
try:
    for row in q("SELECT * FROM notifications ORDER BY day DESC LIMIT 40"):
        print(row)
except Exception as e:
    print("notif err", e)
    # try schema
    try:
        print(q("SELECT * FROM notifications LIMIT 3"))
    except Exception as e2:
        print(e2)

print("\n======= AGENT SOCIAL POSTS =======")
for row in q("SELECT * FROM agent_social_media_posts ORDER BY day"):
    print(row)

print("\n======= S1 INSIGHTS =======")
ins = nm.market.get_group_insights(group_id="S1")
print(json.dumps(ins, indent=2, default=str)[:8000])

