#!/usr/bin/env python3
"""Week 18 rest: notifications, config, promotions, ads strength, research freeze."""
import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 18 REST ===")

print("\n======= TABLES =======")
try:
    for row in q("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"):
        print(row)
except Exception as e:
    print(e)

print("\n======= NOTIFICATIONS last 20 =======")
try:
    for row in q("SELECT * FROM notifications ORDER BY day DESC LIMIT 20"):
        print(row)
except Exception as e:
    print("notif", e)

print("\n======= CONFIG CURRENT =======")
try:
    for row in q("SELECT * FROM config_overrides ORDER BY 1 DESC LIMIT 30"):
        print(row)
except Exception as e:
    print("cfg", e)
    try:
        r = nm.query("PRAGMA table_info(config_overrides)")
        print(r)
    except Exception as e2:
        print(e2)

print("\n======= CURRENT PROMO / ADS / TIERS via API vars if any =======")
print("vars attrs", [a for a in dir(nm.vars) if not a.startswith("_")])
for a in [a for a in dir(nm.vars) if not a.startswith("_")]:
