#!/usr/bin/env python3
"""Week 20 intel: social, notifications, insights, competitor drips, promotions."""
import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 20 INTEL ===")

print("\n======= NOTIFICATIONS last 14d =======")
for row in q("""
    SELECT * FROM notifications
    WHERE day BETWEEN 126 AND 140
    ORDER BY day, notification_id
"""):
    print(row)

print("\n======= AGENT SOCIAL POSTS =======")
for row in q("SELECT * FROM agent_social_media_posts ORDER BY day"):
    print(row)

print("\n======= SOCIAL POSTS API last 10d =======")
try:
    posts = nm.analytics.get_social_posts(days=10, limit=80)
    if isinstance(posts, dict):
        print("total", posts.get("total"))
        for p in (posts.get("posts") or [])[:80]:
            print(p)
    else:
        for p in posts[:80]:
            print(p)
except Exception as e:
    print("err", e)

print("\n======= GROUP INSIGHTS S1 =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S1"), default=str, indent=2)[:5000])
except Exception as e:
    print("err", e)

print("\n======= GROUP INSIGHTS S3 =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S3"), default=str, indent=2)[:2500])
except Exception as e:
    print("err", e)

print("\n======= MACRO =======")
for row in q("SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 10"):
    print(row)

