#!/usr/bin/env python3
"""Week 21 rest: social, competitor drips, posts, config, B renewals, incremental churn."""
import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 21 REST ===")

print("\n======= SOCIAL POSTS last 10d (API) =======")
try:
    posts = nm.analytics.get_social_posts(days=10, limit=80)
    if isinstance(posts, dict):
        print("keys", posts.keys(), "total", posts.get("total"))
        plist = posts.get("posts") or posts.get("items") or []
    else:
        plist = posts
    for p in plist:
        if isinstance(p, dict):
            pid = p.get("post_id")
            d = p.get("day")
            gid = p.get("group_id")
            persona = p.get("persona_name")
            content = (p.get("content") or "")[:220]
            print(f"  id={pid} d{d} {gid} {persona}: {content}")
        else:
            print(p)
except Exception as e:
    print("social err", type(e), e)

print("\n======= AGENT POSTS TABLE =======")
for row in q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 10"):
    print(row)

print("\n======= NOTIFICATIONS d134-147 =======")
for row in q("SELECT day, kind, message FROM notifications WHERE day BETWEEN 134 AND 147 ORDER BY day"):
    print(row)

