#!/usr/bin/env python3
"""Week 23 intel: social, competitor drips, insights, posts, notifications."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 23 INTEL ===")

print("\n======= MARKET OVERVIEW =======")
ov = nm.market.get_market_overview()
print(json.dumps(ov, indent=2, default=str)[:4000])

print("\n======= S1 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S1"), indent=2, default=str)[:5000])
except Exception as e:
    print("S1 insights err", e)

print("\n======= S2 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S2"), indent=2, default=str)[:2500])
except Exception as e:
    print("S2 insights err", e)

print("\n======= S3 INSIGHTS =======")
try:
    print(json.dumps(nm.market.get_group_insights(group_id="S3"), indent=2, default=str)[:2500])
except Exception as e:
    print("S3 insights err", e)

print("\n======= SOCIAL POSTS last 10d (API) =======")
try:
    posts = nm.analytics.get_social_posts(days=10, limit=80)
    print("type", type(posts), "keys" if isinstance(posts, dict) else "")
    if isinstance(posts, dict):
        print("total", posts.get("total"))
        for p in (posts.get("posts") or [])[:80]:
            pid = p.get("post_id")
            d = p.get("day")
            gid = p.get("group_id")
            name = p.get("persona_name")
            content = (p.get("content") or "")[:180]
            print(f"  id={pid} d={d} g={gid} {name}: {content}")
    else:
        print(posts)
except Exception as e:
    print("social err", e)

print("\n======= AGENT SOCIAL POSTS =======")
try:
    for row in q("SELECT * FROM agent_social_media_posts ORDER BY day"):
        print(row)
except Exception as e:
    print("agent posts err", e)
    try:
        print(q("SELECT * FROM agent_social_media_posts LIMIT 5"))
    except Exception as e2:
        print("also fail", e2)

print("\n======= NOTIFICATIONS last 14d =======")
for row in q(f"SELECT * FROM notifications WHERE day > {day - 14} ORDER BY day, notification_id"):
    print(row)

