#!/usr/bin/env python3
"""Week 23 rest2: social posts, competitor drips, agent post effects, notifications."""
import json
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 23 REST2 ===")

print("\n======= NOTIFICATIONS last 21d =======")
try:
    for row in q(f"SELECT day, notification_id, kind, title, body FROM notifications WHERE day > {day-21} ORDER BY day, notification_id"):
        print(row)
except Exception as e:
    print("notif schema?", e)
    for row in q(f"SELECT * FROM notifications WHERE day > {day-14} ORDER BY day LIMIT 50"):
        print(row)

print("\n======= AGENT SOCIAL =======")
try:
    for row in q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 10"):
        print(row)
except Exception as e:
    print("agent table", e)

print("\n======= SOCIAL API last 14d =======")
posts = nm.analytics.get_social_posts(days=14, limit=100)
if isinstance(posts, dict):
    print("total", posts.get("total"))
    for p in (posts.get("posts") or []):
        content = (p.get("content") or "")[:220]
        print(f"id={p.get('post_id')} d={p.get('day')} g={p.get('group_id')} {p.get('persona_name')}: {content}")
else:
    print(posts)

print("\n======= SOCIAL TABLE last 14d =======")
try:
    for row in q(f"SELECT * FROM social_media_posts WHERE day > {day-14} ORDER BY day, post_id"):
        print(row)
except Exception as e:
    print("social table", e)

print("\n======= RESEARCH PROJECTS TABLE =======")
try:
    for row in q("SELECT * FROM research_projects"):
        print(row)
except Exception as e:
    print(e)

print("\n======= S1 INSIGHTS KEY BITS =======")
ins = nm.market.get_group_insights(group_id="S1")
print(json.dumps(ins, indent=2, default=str)[:8000])

