#!/usr/bin/env python3
"""Scan social for competitor drips d136-161 and pull latest support post for reply."""
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

print("=== COMPETITOR / QUALITY MENTIONS ===")
posts = nm.analytics.get_social_posts(days=30, limit=200)
items = posts.get("posts") if isinstance(posts, dict) else posts
print("n posts", len(items) if items else 0, "total", posts.get("total") if isinstance(posts, dict) else "")
for p in items or []:
    c = p.get("content") or ""
    cl = c.lower()
    if any(k in cl for k in ["quality", "boost", "rival", "nexgen", "apex", "cloudpeak", "feature suite", "0.0"]):
        print(f"id={p.get('post_id')} d={p.get('day')} g={p.get('group_id')}: {c[:260]}")
        print("---")

print("\n=== FRESH SUPPORT POSTS d155-161 ===")
for p in items or []:
    c = p.get("content") or ""
    cl = c.lower()
    if p.get("day", 0) >= 154 and any(k in cl for k in ["support", "ticket", "ghost", "wait", "days", "cricket", "unanswered"]):
        print(f"REPLY CANDIDATE id={p.get('post_id')} d={p.get('day')} g={p.get('group_id')} {p.get('persona_name')}: {c[:400]}")
        print("---")

print("\n=== S2/S3/E INSIGHTS SHORT ===")
import json
for g in ["S2", "S3", "E1"]:
    try:
        ins = nm.market.get_group_insights(group_id=g)
        est = ins.get("estimates") or {}
        print(g, "qmin", est.get("quality_floor_q_min"), "wtp", est.get("willingness_to_pay"), "usage", est.get("usage_volume"), "tam", est.get("market_cap"))
        print("  net out", (ins.get("network_influence") or {}).get("outgoing"))
    except Exception as e:
        print(g, e)

