#!/usr/bin/env python3
"""Week 33 intel: social, competitor drips, notifications, #33 effect, config, upgrades."""
import novamind_api as nm

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

print("=== WEEK 33 INTEL ===")

print("\n======= AGENT SOCIAL POSTS =======")
for row in q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 10"):
    print(row)

print("\n======= NOTIFICATIONS last 14d =======")
try:
    for row in q("SELECT * FROM notifications WHERE day BETWEEN 218 AND 231 ORDER BY day"):
        print(row)
except Exception as e:
    print("notif err", type(e), e)

print("\n======= SOCIAL POSTS d225-231 (sample) =======")
posts = nm.analytics.get_social_posts(days=7, limit=50)
print("type", type(posts))
if isinstance(posts, dict):
    print("total", posts.get("total"))
    for p in (posts.get("posts") or [])[:50]:
        print(f"  id={p.get('post_id')} d={p.get('day')} g={p.get('group_id')} persona={p.get('persona_name')}")
        print(f"    {str(p.get('content'))[:280]}")
else:
    print(posts)

print("\n======= NEW S1 B/C mix this week vs last =======")
for lo, hi, label in [(218,224,"w32"), (225,231,"w33")]:
    r = q(f"""
        SELECT s.plan, COUNT(*) n
        FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
        WHERE c.group_id='S1' AND c.created_day BETWEEN {lo} AND {hi}
          AND s.status IN ('subscribed','cancelled')
        GROUP BY s.plan
    """)
    print(label, r)

print("\n======= CONFIG OVERRIDES recent =======")
for row in q("SELECT * FROM config_overrides ORDER BY day DESC LIMIT 20"):
    print(row)

print("\n======= RESEARCH PROJECTS STATUS =======")
try:
    for row in q("SELECT * FROM research_projects"):
        print(row)
except Exception as e:
    print("research table err", e)

