#!/usr/bin/env python3
"""Week 36 intel: social, competitor, quality, notifications, agent posts."""
import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 36 INTEL ===")

print("\n======= SOCIAL POSTS last 14d (API) =======")
try:
    res = nm.analytics.get_social_posts(days=14, limit=80)
    posts = res.get("posts") if isinstance(res, dict) else res
    print("total", res.get("total") if isinstance(res, dict) else len(posts or []))
    for p in (posts or [])[:80]:
        pid = p.get("post_id")
        d = p.get("day")
        gid = p.get("group_id")
        persona = p.get("persona_name")
        content = (p.get("content") or "")[:180]
        print(f"  id={pid} d={d} {gid} {persona}: {content}")
except Exception as e:
    print("social err", e)

print("\n======= AGENT SOCIAL POSTS =======")
try:
    for row in q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 8"):
        print(row)
except Exception as e:
    print("agent posts table err", e)
    # try alternate
    try:
        print(nm.query("SELECT name FROM sqlite_master WHERE type='table'"))
    except Exception as e2:
        print(e2)

print("\n======= NOTIFICATIONS =======")
try:
    for row in q("SELECT * FROM notifications ORDER BY day DESC LIMIT 20"):
        print(row)
except Exception as e:
    print("notif err", e)

print("\n======= SOCIAL TABLE last 20 =======")
try:
    for row in q("SELECT post_id, day, substr(content,1,160) c FROM social_media_posts ORDER BY day DESC, post_id DESC LIMIT 25"):
        print(row)
except Exception as e:
    print("sm table err", e)

