#!/usr/bin/env python3
"""Week 37 intel: social, competitor drips, market, config, agent posts."""
import novamind_api as nm
import json

def q(sql):
    r = nm.query(sql)
    return r.get("rows") or []

day = nm.vars.current_day
print(f"=== DAY {day} WEEK 37 INTEL ===")

print("\n======= MARKET OVERVIEW =======")
print(nm.market.get_market_overview())

print("\n======= SOCIAL POSTS last 14d (API) =======")
try:
    posts = nm.analytics.get_social_posts(days=14, limit=80)
    print("type", type(posts), "keys", posts.keys() if isinstance(posts, dict) else None)
    items = posts.get("posts", posts) if isinstance(posts, dict) else posts
    print("n", len(items) if items else 0, "total", posts.get("total") if isinstance(posts, dict) else "")
    for p in (items or [])[:80]:
        pid = p.get("post_id")
        d = p.get("day")
        gid = p.get("group_id")
        persona = p.get("persona_name")
        content = (p.get("content") or "")[:180]
        print(f"  id={pid} d={d} {gid} {persona}: {content}")
except Exception as e:
    print("err", e)

print("\n======= AGENT SOCIAL POSTS =======")
try:
    for row in q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 20"):
        print(row)
except Exception as e:
    print("err agent posts", e)

print("\n======= NOTIFICATIONS (recent) =======")
try:
    for row in q("SELECT * FROM notifications ORDER BY day DESC LIMIT 30"):
        print(row)
except Exception as e:
    print("err notif", e)
    try:
        # try alternative
        print("tables probe")
    except Exception:
        pass

